    /** current zoom level */
    zoom: number;
  }

  // noinspection JSUnusedGlobalSymbols
  interface ToolbarButtonKeys {
    [PLUGIN_ZOOM]: null;
  }

  /** Zoom plugin ref */
  interface ZoomRef {
    /** current zoom level */
    zoom: number;
    /** minimum zoom level */
    minZoom: number;
    /** maximum zoom level */
    maxZoom: number;
    /** horizontal offset */
    offsetX: number;
    /** vertical offset */
    offsetY: number;
    /** if `true`, zoom is unavailable for the current slide */
    disabled: boolean;
    /** increase zoom level using `zoomInMultiplier` */
    zoomIn: Callback;
    /** decrease zoom level using `zoomInMultiplier` */
    zoomOut: Callback;
    /** change zoom level */
    changeZoom: (targetZoom: number, rapid?: boolean, dx?: number, dy?: number) => void;
  }
}

export default Zoom;
